def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    """Fixes for the following issues on windows
    - https://bugs.python.org/issue8557
    - windows does not parse shebangs

    This function also makes deep-path shebangs work just fine
    """
    # Handle issue #8557
    if len(cmd) > 0 and cmd[0] == 'python':
        return ('python.exe',) + cmd[1:]

    # Make deep-path shebangs work
    prefix = None
    for i, arg in enumerate(cmd):
        if arg.startswith('#!'):
            prefix = cmd[:i+1]
            break

    if prefix:
        cmd = cmd[len(prefix):]
        if len(cmd) == 0:
            raise ValueError("Empty command after parsing shebang")

    return cmd

def normalize_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if check_windows():
        if cmd[0].startswith('#!'):
            # Remove the shebang line if it exists
            cmd = cmd[1:]
        elif not cmd[0].endswith('.exe'):
            # Add an extension to the first command if it doesn't have one
            cmd = (cmd[0] + '.exe', *cmd[1:])
    return cmd

def check_windows():
    return os.name == 'nt'

def normalize_shebang_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if check_windows():
        # Normalize the shebang line on windows if it's present
        if cmd[0].startswith('#!'):
            cmd = cmd[1:]
    return cmd

def normalize_deep_path_shebang_cmd(cmd: tuple[str, ...]) -> tuple[str, ...]:
    if check_windows():
        # Normalize the shebang line with a deep path on windows if it's present
        if cmd[0].startswith('#!') and '\\' in cmd[0][2:]:
            cmd = (cmd[0].split('\\', 1)[1], *cmd[1:])
    return cmd
