def resolve_string(self, matcher):
    """
    Resolve a matcher and get the corresponding value based on the matcher's name and optional default value.
    If the variable is not defined in the environment and no default value is provided, raise an error.
    """
    name = matcher.group(1)
    default_value = matcher.group(2)

    if default_value is None:
        if name in os.environ:
            return os.environ[name]
        else:
            raise KeyError(f"The variable {name} is not defined in the environment.")
    else:
        return os.environ.get(name, default_value)

