            arg['value'] = defaults[arg['value']] if arg['value'] in defaults else arg['value']
            arg['unset'] = False
        elif arg['value'] is None:
            if arg['name'] == 'name2':
                arg['unset'] = True
                arg['value'] = 'value2'
            elif arg['name'] == 'name3':
                arg['unset'] = True
                arg['value'] = 'value3'
            elif arg['name'] == 'name4':
                arg['unset'] = True
                arg['value'] = 'value4'

    if merged:
        # Merge the resolved values with the spec values.
        for arg in spec.get('arguments'):
            if arg['name'] in defaults:
                arg['value'] = defaults[arg['value']] if arg['value'] in defaults else arg['value']
            elif arg['value'] is None:
