namespace YourNamespace
{
    public class ChoiceArgsValidator
    {
        private Dictionary<string, List<string>> _availableChoices;

        public ChoiceArgsValidator(Dictionary<string, List<string>> availableChoices)
        {
            _availableChoices = availableChoices;
        }

        public bool Validate(string argumentName, string argumentValue)
        {
            if (!_availableChoices.ContainsKey(argumentName))
            {
                throw new ArgumentException($"No available choices for argument: {argumentName}");
            }

            if (!_availableChoices[argumentName].Contains(argumentValue))
            {
                throw new ArgumentException($"Invalid argument value: {argumentValue} for argument: {argumentName}. Available choices: {string.Join(", ", _availableChoices[argumentName])}");
            }

            return true;
        }
    }
}
