def create_complex_arg_type(subcommand, type_name, option_name, spec_option):
    # Build the complex argument type
    if subcommand is None or subcommand == '':
        raise ValueError("subcommand is required")
    if type_name is None or type_name == '':
        raise ValueError("type_name is required")
    if option_name is None or option_name == '':
        raise ValueError("option_name is required")
    if spec_option is None:
        raise ValueError("spec_option is required")

    # Check if the type name is already defined
    if complex_type := self.get_type(type_name):
        return complex_type

    # Create the new type
    complex_type = self.add_type(type_name, complex(spec_option))

    # Add the type to the subcommand
    if subcommand_obj := self.get_subcommand(subcommand):
        subcommand_obj.seq.ArgumentTypes.add(complex_type)

