def _convert_non_cli_args(self, parser_name, values_dict):
    """Casts arguments to correct types by modifying values_dict param.

    By default all the values are strings.

    :param parser_name: The command name, e.g. main, virsh, ospd, etc
    :param values_dict: The dict of with arguments
    """

    # Load the config, if a global one exists
    if self.config_file:
        self.config = self.load_config(parser_name)

    # Load the command-line parameters
    for param in self.params:
        cls = param.get("type")
        if cls is None:
            cls = str
        if param["name"] not in values_dict:
            continue
        try:
            values_dict[param["name"]] = cls(values_dict[param["name"]])
        except ValueError as e:
            raise ValueError(f"Error converting parameter '{param['name']}' to type '{cls.__name__}': {e}")

